// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        address owner = address(c.owner());
        vm.deal(owner, 1 ether);
        vm.prank(owner);
        (bool sent, ) = address(c).call{value: 1 wei}("");
        require(sent, "fallback failed");

        c.sendMoney(address(c), 1);

        uint256 deposits = c.depositsCount();
        assertTrue(deposits == 2, "depositsCount should be 2 but was not");
    }
}
